SET local check_function_bodies = off;

CREATE TABLE "better_supabase"."document_suggestions" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "document_id" uuid                     NOT NULL,
  "tenant_id"   uuid                     NOT NULL,
  "payload"     bytea                    NOT NULL,
  "summary"     text,
  "status"      text                     NOT NULL DEFAULT 'open'::text,
  "created_by"  uuid,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "decided_by"  uuid,
  "decided_at"  timestamp with time zone,
  "note"        text,
  CONSTRAINT "document_suggestions_note_check" CHECK (((length(note) >= 1) AND (length(note) <= 500))),
  CONSTRAINT "document_suggestions_pkey" PRIMARY KEY (id),
  CONSTRAINT "document_suggestions_status_check" CHECK ((status = ANY (ARRAY['open'::text, 'accepted'::text, 'rejected'::text, 'withdrawn'::text]))),
  CONSTRAINT "document_suggestions_summary_check" CHECK (((length(summary) >= 1) AND (length(summary) <= 500)))
);

ALTER TABLE "better_supabase"."document_suggestions"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION api.decide_document_suggestion (
  suggestion_id uuid,
  decision      text,
  note          text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE sql
  SET search_path TO ''
  AS $function$ select "better_supabase"."decide_document_suggestion"($1, $2, $3) $function$;

CREATE OR REPLACE FUNCTION api.list_document_suggestions (
  document_id uuid,
  status      text DEFAULT 'open'::text
)
  RETURNS jsonb
  LANGUAGE sql
  SET search_path TO ''
  AS $function$ select "better_supabase"."list_document_suggestions"($1, $2) $function$;

CREATE OR REPLACE FUNCTION api.name_document_version (
  document_id uuid,
  version_id  uuid,
  label       text
)
  RETURNS boolean
  LANGUAGE sql
  SET search_path TO ''
  AS $function$ select "better_supabase"."name_document_version"($1, $2, $3) $function$;

CREATE OR REPLACE FUNCTION api.suggest_document_change (
  document_id uuid,
  payload     text,
  summary     text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE sql
  SET search_path TO ''
  AS $function$ select "better_supabase"."suggest_document_change"($1, $2, $3) $function$;

CREATE OR REPLACE FUNCTION better_supabase.data_lifecycle_tables()
  RETURNS TABLE (
    subject  text,
    name     text,
    tbl      text,
    col      text,
    purge    boolean,
    omit     text[],
    exported boolean
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select t.subject, t.name, t.tbl, t.col, t.purge,
    t.omit || array(
      select a.attname::text
      from pg_catalog.pg_attribute a
      where a.attrelid = to_regclass(t.tbl)
        and a.attnum > 0
        and not a.attisdropped
        and a.attname ~* 'token|secret|_hash|password|api_key|license_key'
        and a.attname <> t.col
        and not a.attname = any(t.omit)
      order by a.attnum
    ) as omit,
    t.exported
  from (
  select * from (values
    ('user', 'better_supabase.audit_events', '"better_supabase"."audit_events"', 'actor_id', false, array['old_record', 'new_record', 'impersonated_by', 'impersonation_reason', 'support_session_id']::text[], true),
